static void print_usage_lines(FILE *out)
{
    fprintf(out, "Usage: %s [options] [-f] <file> [--] [args...]\n", program_name);
    fprintf(out, "   %s [options] -r <code> [--] [args...]\n", program_name);
    fprintf(out, "   %s [options] [-B <begin_code>] -R <code> [-E <end_code>] [--] [args...]\n", program_name);
    fprintf(out, "   %s [options] [-B <begin_code>] -F <file> [-E <end_code>] [--] [args...]\n", program_name);
    fprintf(out, "   %s [options] -S <addr>:<port> [-t docroot] [router]\n", program_name);
    fprintf(out, "   %s [options] -- [args...]\n", program_name);
    fprintf(out, "   %s [options] -a\n", program_name);
}

static void print_help(FILE *out)
{
    print_usage_lines(out);
    fputs(
        "\n"
        "  -a               Run as interactive shell (requires readline extension)\n"
        "  -c <path>|<file> Look for php.ini file in this directory\n"
        "  -n               No configuration (ini) files will be used\n"
        "  -d foo[=bar]     Define INI entry foo with value 'bar'\n"
