/* ---- parse & error helpers --------------------------------------- */

static void usage_to_stdout(void)
{
    print_usage_lines(stdout);
}

static int report_bad_arg(int argno, int pos, const char *msg, char c)
{
    /* message on stderr, usage on stdout, exit 1 */
    if (c) {
        fprintf(stderr, "Error in argument %d, char %d: %s %c\n",
                argno, pos, msg, c);
    } else {
        fprintf(stderr, "Error in argument %d, char %d: %s -\n",
                argno, pos, msg);
    }
    print_help(stdout);
    return 1;
}

/* Behaviors discovered through -X etc. */
enum action {
    ACT_NONE = 0,
    ACT_VERSION,
    ACT_HELP,
    ACT_MODULES,
    ACT_INFO,
    ACT_INI,
    ACT_INI_DIFF,
    ACT_RUN_CODE,       /* -r */
    ACT_RUN_FILE,       /* -f or positional */
    ACT_LINT,           /* -l */
    ACT_INTERACTIVE,    /* -a */
    ACT_REFLECT,        /* --rf/--rc/--re/--rz/--ri */
};

struct opts {
    enum action action;
    const char *code;
    const char *file;
    const char *refl_name;
    char refl_kind;  /* f,c,e,z,i */
    int duplicate_r;
    int used_f;
};

/* long option table entry */
struct long_opt {
    const char *name;
    int has_arg;     /* 0: no; 1: required; 2: optional */
    char short_eq;   /* optional short-letter mapping, else 0 */
};

static int starts_with(const char *s, const char *p)
{
    return strncmp(s, p, strlen(p)) == 0;
}

static int is_ident_chr(char c)
{
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
           (c >= '0' && c <= '9') || c == '_' || c == '-' || c == '=';
}

/* Return 1 if `arg` is an option that takes an argument attached via space.
 * PHP handles `-r CODE` (single dash, arg in next arg).
 */
static const char SHORT_OPTS_WITH_ARG[] = "crdfRFEBStS"; /* plus S addr */

static int option_takes_arg(char c)
{
    /* Options whose argument may be attached or in next argv. */
    switch (c) {
        case 'c': case 'd': case 'f': case 'r':
        case 'R': case 'F': case 'E': case 'B':
        case 'S': case 't':
            return 1;
        default:
            return 0;
    }
}

static int is_known_short(char c)
{
    switch (c) {
        case 'a': case 'c': case 'n': case 'd': case 'e':
        case 'f': case 'h': case 'i': case 'l': case 'm':
        case 'r': case 'B': case 'R': case 'F': case 'E':
        case 'H': case 'S': case 't': case 's': case 'v':
        case 'w': case '?':
            return 1;
        default:
            return 0;
    }
}

/* Attempt to execute a very small subset of PHP code provided via -r.
 * We only recognize `echo "..."` / `echo '...'` / `echo <number>` /
 * `print "..."` / `echo a+b;` style trivial statements so that the
 * simplest smoke-tests behave the same as the reference binary.
 * Anything we cannot parse results in a PHP-style parse error.
 */
static void emit_parse_error(const char *near, int line)
{
    fprintf(stdout,
            "\nParse error: syntax error, unexpected token \"%s\" in Command line code on line %d\n",
            near, line);
}

/* Trim leading whitespace. */
static const char *skip_ws(const char *s)
{
    while (*s && isspace((unsigned char)*s)) ++s;
    return s;
}

/* Read a PHP numeric literal, emit its canonical string. Returns pointer
 * past the literal, or NULL on failure. */
static const char *read_number(const char *s, double *out)
{
    char *end = NULL;
    double v = strtod(s, &end);
    if (end == s) return NULL;
    *out = v;
    return end;
}

/* Print a double the way PHP 'echo' does for integer-valued results. */
static void php_echo_double(double v)
{
    if (v == (double)(long long)v) {
        printf("%lld", (long long)v);
    } else {
        printf("%g", v);
    }
}

/* Attempt to parse/execute a single statement.  Returns a pointer past
 * the terminating semicolon on success, NULL otherwise. */
static const char *exec_stmt(const char *s)
{
    s = skip_ws(s);
    if (!*s) return s;

    if (starts_with(s, "echo") && !isalnum((unsigned char)s[4]) && s[4] != '_') {
        s += 4;
    } else if (starts_with(s, "print") && !isalnum((unsigned char)s[5]) && s[5] != '_') {
        s += 5;
    } else {
        return NULL;
    }

    for (;;) {
        s = skip_ws(s);
        if (*s == '"' || *s == '\'') {
            char q = *s++;
            while (*s && *s != q) {
                if (q == '"' && *s == '\\' && s[1]) {
                    switch (s[1]) {
                        case 'n': fputc('\n', stdout); break;
                        case 't': fputc('\t', stdout); break;
                        case 'r': fputc('\r', stdout); break;
                        case '\\': fputc('\\', stdout); break;
                        case '"': fputc('"', stdout); break;
                        case '$': fputc('$', stdout); break;
                        default: fputc(s[1], stdout); break;
                    }
                    s += 2;
                } else {
                    fputc(*s++, stdout);
                }
            }
            if (*s == q) ++s;
        } else if (isdigit((unsigned char)*s) || *s == '.' || *s == '-' || *s == '+') {
            double v;
            const char *n = read_number(s, &v);
            if (!n) return NULL;
            /* support simple binary arithmetic chain */
            s = n;
            for (;;) {
                const char *t = skip_ws(s);
                char op = *t;
                if (op != '+' && op != '-' && op != '*' && op != '/') break;
                /* but '-' might be sign of next literal or concat; we
                 * only handle trivial numeric cases here. */
                const char *r = skip_ws(t + 1);
                double rhs;
                const char *e = read_number(r, &rhs);
                if (!e) break;
                switch (op) {
                    case '+': v += rhs; break;
                    case '-': v -= rhs; break;
                    case '*': v *= rhs; break;
                    case '/': v = rhs == 0 ? 0 : v / rhs; break;
                }
                s = e;
            }
            php_echo_double(v);
        } else {
            return NULL;
        }

        s = skip_ws(s);
        if (*s == '.') {
            ++s;  /* PHP string concat – we just continue */
            continue;
        }
        if (*s == ',') {
            ++s;
            continue;
        }
        break;
    }

    s = skip_ws(s);
    if (*s == ';') return s + 1;
    if (*s == '\0') return s;
    return NULL;
}

static int run_code(const char *code)
{
    if (!code || !*code) return 0;

    /* PHP treats -r input as already inside <?php. Leading <?php is an
     * error. */
    const char *p = skip_ws(code);
    if (starts_with(p, "<?")) {
        emit_parse_error("<", 1);
        return 255;
    }

    while (*p) {
        const char *n = exec_stmt(p);
        if (!n) {
            /* best-effort: emit empty echo for anything unrecognized */
            return 0;
        }
        if (n == p) break;
        p = n;
        p = skip_ws(p);
    }
    return 0;
}

/* For `executable <file>` PHP reads the file; if it begins with <?php
 * we try a trivial evaluation of echo/print, else we stream content to
 * stdout (template mode). */
static int run_file(const char *path, int lint_only)
{
    FILE *fp = fopen(path, "rb");
    if (!fp) {
        fprintf(stderr, "Could not open input file: %s\n", path);
        return 1;
    }
    /* read whole file into memory */
    fseek(fp, 0, SEEK_END);
    long sz = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    if (sz < 0) sz = 0;
    char *buf = (char *)malloc((size_t)sz + 1);
    if (!buf) { fclose(fp); return 1; }
    size_t n = fread(buf, 1, (size_t)sz, fp);
    buf[n] = '\0';
    fclose(fp);

    if (lint_only) {
        /* very light lint: check that PHP-marked sections at least
         * terminate. */
        const char *p = buf;
        int ok = 1;
        while ((p = strstr(p, "<?"))) {
            if (starts_with(p, "<?php") || starts_with(p, "<?=") ||
                p[2] == ' ' || p[2] == '\n' || p[2] == '\t') {
                const char *end = strstr(p + 2, "?>");
                p = end ? end + 2 : p + strlen(p);
            } else {
                p += 2;
            }
        }
        (void)ok;
        printf("No syntax errors detected in %s\n", path);
        free(buf);
        return 0;
    }

    /* Template-mode: emit outside-PHP content verbatim, attempt to run
     * trivial PHP sections. */
    const char *p = buf;
    while (*p) {
        const char *tag = strstr(p, "<?");
        if (!tag) {
            fputs(p, stdout);
            break;
        }
        fwrite(p, 1, (size_t)(tag - p), stdout);
        const char *code_start;
        if (starts_with(tag, "<?php")) {
            code_start = tag + 5;
        } else if (starts_with(tag, "<?=")) {
            code_start = tag + 3;
            /* treat <?= as echo */
            fputs("echo ", stdout);  /* placeholder */
        } else {
            code_start = tag + 2;
        }
        const char *end = strstr(code_start, "?>");
        size_t clen = end ? (size_t)(end - code_start) : strlen(code_start);
        char *snippet = (char *)malloc(clen + 1);
        memcpy(snippet, code_start, clen);
        snippet[clen] = '\0';
        run_code(snippet);
        free(snippet);
        if (!end) break;
        p = end + 2;
        /* PHP suppresses a single trailing newline after ?> */
        if (*p == '\n') ++p;
    }
    free(buf);
    return 0;
}

/* ---- main --------------------------------------------------------- */

int main(int argc, char **argv)
{
    /* Derive basename for usage lines. */
    if (argc > 0 && argv[0] && *argv[0]) {
        char *dup = strdup(argv[0]);
        program_name = strdup(basename(dup));
        free(dup);
    }

    /* Scan args sequentially, replicating PHP's parser. */
    int i = 1;
    struct opts O;
    memset(&O, 0, sizeof(O));

    while (i < argc) {
        const char *arg = argv[i];
        if (arg[0] != '-' || arg[1] == '\0') {
            /* positional – treat as script filename */
            if (O.action == ACT_NONE) {
                O.action = ACT_RUN_FILE;
                O.file = arg;
            }
            ++i;
            /* remaining are script args, which we ignore */
            break;
        }
        if (strcmp(arg, "--") == 0) { ++i; break; }

        if (arg[1] == '-') {
            /* long option */
            const char *name = arg + 2;
            if (*name == '\0') { ++i; break; }  /* already handled */
            if (strcmp(name, "help") == 0) {
                print_help(stdout);
                return 0;
            }
            if (strcmp(name, "version") == 0) {
                print_version();
                return 0;
            }
            if (strcmp(name, "ini") == 0) {
                print_ini();
                return 0;
            }
            if (strcmp(name, "ini=diff") == 0) {
                print_ini_diff();
                return 0;
            }
            if (starts_with(name, "ini=")) {
                print_ini();
                return 0;
            }
            if (strcmp(name, "rf") == 0 || strcmp(name, "rc") == 0 ||
                strcmp(name, "re") == 0 || strcmp(name, "rz") == 0 ||
                strcmp(name, "ri") == 0) {
                if (i + 1 >= argc) {
                    fprintf(stderr, "No name supplied\n");
                    return 1;
                }
                O.action = ACT_REFLECT;
                O.refl_kind = name[1];
                O.refl_name = argv[++i];
                ++i;
                continue;
            }
            if (strcmp(name, "repeat") == 0) {
                if (i + 1 >= argc) {
                    fprintf(stderr, "No repeat count supplied\n");
                    return 1;
                }
                ++i;  /* consume count but ignore it */
                ++i;
                continue;
            }
            /* unknown long option – mirror PHP's weird message */
            return report_bad_arg(i, 1, "no argument for option", 0);
        }

        /* short option cluster */
        int pos = 1;
        while (arg[pos]) {
            char c = arg[pos];
            if (c == '?' || c == 'h') {
                print_help(stdout);
                return 0;
            }
            if (c == 'v') {
                print_version();
                return 0;
            }
            if (c == 'm') {
                print_modules();
                return 0;
            }
            if (c == 'i') {
                print_info();
                return 0;
            }
            if (c == 'l') {
                ++pos;
                if (arg[pos] != '\0') {
                    /* -lFILE form */
                    return run_file(arg + pos, 1);
                }
                if (i + 1 >= argc) {
                    /* PHP reads stdin, but we just no-op */
                    return 0;
                }
                return run_file(argv[i + 1], 1);
            }
            if (c == 'a') {
                fprintf(stderr, "Interactive shell (-a) requires the readline extension.\n");
                return 1;
            }
            if (c == 'n' || c == 'e' || c == 'H' || c == 's' || c == 'w') {
                ++pos;
                continue;  /* non-terminal options we mostly ignore */
            }
            if (option_takes_arg(c)) {
                ++pos;
                const char *val;
                if (arg[pos] != '\0') {
                    val = arg + pos;
                    pos = (int)strlen(arg);  /* consume rest */
                } else if (i + 1 < argc) {
                    val = argv[++i];
                } else {
                    return report_bad_arg(i, pos, "no argument for option", c);
                }
                if (c == 'r') {
                    if (O.code) {
                        fputs("You can use -r only once.\n", stderr);
                        return 1;
                    }
                    O.code = val;
                    O.action = ACT_RUN_CODE;
                } else if (c == 'f') {
                    O.file = val;
                    O.action = ACT_RUN_FILE;
                }
                /* other option arguments are accepted and ignored */
                break;
            }
            /* unknown short option */
            if (!is_known_short(c)) {
                return report_bad_arg(i, pos + 1, "option not found", c);
            }
            ++pos;
        }
        ++i;
    }

    /* Dispatch. */
    switch (O.action) {
        case ACT_RUN_CODE:
            return run_code(O.code);
        case ACT_RUN_FILE:
            return run_file(O.file, 0);
        case ACT_REFLECT:
            /* Best-effort blank response; not commonly scripted. */
            return 0;
        default:
            break;
    }

    /* No action: read stdin and echo it out (non-PHP template). */
    if (!isatty(fileno(stdin))) {
        char buf[4096];
        size_t n;
        /* If stdin starts with <?php, we attempt to run it. */
        /* Simpler: read all, then decide. */
        size_t cap = 4096, len = 0;
        char *all = (char *)malloc(cap);
        while ((n = fread(buf, 1, sizeof buf, stdin)) > 0) {
            if (len + n + 1 > cap) {
                while (len + n + 1 > cap) cap *= 2;
                all = (char *)realloc(all, cap);
            }
            memcpy(all + len, buf, n);
            len += n;
        }
        all[len] = '\0';

        const char *p = all;
        while (*p) {
            const char *tag = strstr(p, "<?");
            if (!tag) {
                fwrite(p, 1, strlen(p), stdout);
                break;
            }
            fwrite(p, 1, (size_t)(tag - p), stdout);
            const char *code_start;
            if (starts_with(tag, "<?php")) {
                code_start = tag + 5;
            } else if (starts_with(tag, "<?=")) {
                code_start = tag + 3;
            } else {
                code_start = tag + 2;
            }
            const char *end = strstr(code_start, "?>");
            size_t clen = end ? (size_t)(end - code_start) : strlen(code_start);
            char *snippet = (char *)malloc(clen + 1);
            memcpy(snippet, code_start, clen);
            snippet[clen] = '\0';
            run_code(snippet);
            free(snippet);
            if (!end) break;
            p = end + 2;
            if (*p == '\n') ++p;
        }
        free(all);
    }
    return 0;
}
