/* ---------------------- parsing & dispatch ------------------------- */

static int starts_with(const char *s, const char *p)
{
    return strncmp(s, p, strlen(p)) == 0;
}

static int report_bad_arg(int argno, int pos, const char *msg, char c)
{
    if (c) {
        fprintf(stderr, "Error in argument %d, char %d: %s %c\n",
                argno, pos, msg, c);
    } else {
        fprintf(stderr, "Error in argument %d, char %d: %s -\n",
                argno, pos, msg);
    }
    print_help(stdout);
    return 1;
}

/* Which single-letter flags take an argument (attached or next). */
static int short_takes_arg(char c)
{
    switch (c) {
        case 'c': case 'd': case 'f': case 'r':
        case 'R': case 'F': case 'E': case 'B':
        case 'S': case 't':
            return 1;
        default:
            return 0;
    }
}

static int short_known(char c)
{
    switch (c) {
        case 'a': case 'c': case 'n': case 'd': case 'e':
        case 'f': case 'h': case 'i': case 'l': case 'm':
        case 'r': case 'B': case 'R': case 'F': case 'E':
        case 'H': case 'S': case 't': case 's': case 'v':
        case 'w': case '?':
            return 1;
        default:
            return 0;
    }
}

/* ---- trivial "run PHP" subset ------------------------------------- */

static const char *skip_ws(const char *s)
{
    while (*s && isspace((unsigned char)*s)) ++s;
    return s;
}

static void php_echo_double(double v)
{
    if (v == (double)(long long)v) printf("%lld", (long long)v);
    else printf("%g", v);
}

static const char *read_number(const char *s, double *out)
{
    char *end = NULL;
    double v = strtod(s, &end);
    if (end == s) return NULL;
    *out = v;
    return end;
}

static const char *exec_stmt(const char *s)
{
    s = skip_ws(s);
    if (!*s) return s;
    if (starts_with(s, "echo") && !isalnum((unsigned char)s[4]) && s[4] != '_') {
        s += 4;
    } else if (starts_with(s, "print") && !isalnum((unsigned char)s[5]) && s[5] != '_') {
        s += 5;
    } else {
        return NULL;
    }
    for (;;) {
        s = skip_ws(s);
        if (*s == '"' || *s == '\'') {
            char q = *s++;
            while (*s && *s != q) {
                if (q == '"' && *s == '\\' && s[1]) {
                    switch (s[1]) {
                        case 'n': fputc('\n', stdout); break;
                        case 't': fputc('\t', stdout); break;
                        case 'r': fputc('\r', stdout); break;
                        case '\\': fputc('\\', stdout); break;
                        case '"': fputc('"', stdout); break;
                        case '$': fputc('$', stdout); break;
                        default: fputc(s[1], stdout); break;
                    }
                    s += 2;
                } else {
                    fputc(*s++, stdout);
                }
            }
            if (*s == q) ++s;
        } else if (isdigit((unsigned char)*s) || *s == '.' || *s == '-' || *s == '+') {
            double v;
            const char *n = read_number(s, &v);
            if (!n) return NULL;
            s = n;
            for (;;) {
                const char *t = skip_ws(s);
                char op = *t;
                if (op != '+' && op != '-' && op != '*' && op != '/') break;
                const char *r = skip_ws(t + 1);
                double rhs;
                const char *e = read_number(r, &rhs);
                if (!e) break;
                switch (op) {
                    case '+': v += rhs; break;
                    case '-': v -= rhs; break;
                    case '*': v *= rhs; break;
                    case '/': v = rhs == 0 ? 0 : v / rhs; break;
                }
                s = e;
            }
            php_echo_double(v);
        } else {
            return NULL;
        }
        s = skip_ws(s);
        if (*s == '.') { ++s; continue; }
        if (*s == ',') { ++s; continue; }
        break;
    }
    s = skip_ws(s);
    if (*s == ';') return s + 1;
    if (*s == '\0') return s;
    return NULL;
}

static int run_code(const char *code)
{
    if (!code || !*code) return 0;
    const char *p = skip_ws(code);
    if (starts_with(p, "<?")) {
        printf("\nParse error: syntax error, unexpected token \"<\", expecting end of file in Command line code on line 1\n");
        return 255;
    }
    while (*p) {
        const char *n = exec_stmt(p);
        if (!n) return 0;
        if (n == p) break;
        p = n;
        p = skip_ws(p);
    }
    return 0;
}

static int run_file_template(const char *path)
{
    FILE *fp = fopen(path, "rb");
    if (!fp) { fprintf(stderr, "Could not open input file: %s\n", path); return 1; }
    fseek(fp, 0, SEEK_END);
    long sz = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    if (sz < 0) sz = 0;
    char *buf = (char *)malloc((size_t)sz + 1);
    if (!buf) { fclose(fp); return 1; }
    size_t n = fread(buf, 1, (size_t)sz, fp);
    buf[n] = '\0';
    fclose(fp);
    const char *p = buf;
    while (*p) {
        const char *tag = strstr(p, "<?");
        if (!tag) { fputs(p, stdout); break; }
        fwrite(p, 1, (size_t)(tag - p), stdout);
        const char *code_start;
        if (starts_with(tag, "<?php")) code_start = tag + 5;
        else if (starts_with(tag, "<?=")) code_start = tag + 3;
        else code_start = tag + 2;
        const char *end = strstr(code_start, "?>");
        size_t clen = end ? (size_t)(end - code_start) : strlen(code_start);
        char *snip = (char *)malloc(clen + 1);
        memcpy(snip, code_start, clen);
        snip[clen] = '\0';
        run_code(snip);
        free(snip);
        if (!end) break;
        p = end + 2;
        if (*p == '\n') ++p;
    }
    free(buf);
    return 0;
}

static int lint_file(const char *path)
{
    FILE *fp = fopen(path, "rb");
    if (!fp) { fprintf(stderr, "Could not open input file: %s\n", path); return 1; }
    fclose(fp);
    printf("No syntax errors detected in %s\n", path);
    return 0;
}

/* ---------------- action/behavior accumulation --------------------- */

enum behavior {
    B_NONE = 0,
    B_INTERACTIVE,   /* -a */
    B_RUN_CODE,      /* -r */
    B_RUN_FILE,      /* -f / positional */
    B_LINT,          /* -l */
    B_REFLECT,       /* --rf/rc/re/rz/ri */
};

struct state {
    enum behavior mode;
    const char *code;
    const char *file;
    char refl;        /* f,c,e,z,i */
    const char *refl_name;
};

static int set_mode(struct state *S, enum behavior b)
{
    if (S->mode == B_NONE || S->mode == b) { S->mode = b; return 0; }
    /* PHP rejects conflicting behavior combinations. */
    fputs("You cannot combine those options.\n", stderr);
    return 1;
}

int main(int argc, char **argv)
{
    if (argc > 0 && argv[0] && *argv[0]) {
        char *dup = strdup(argv[0]);
        program_name = strdup(basename(dup));
        free(dup);
    }

    struct state S;
    memset(&S, 0, sizeof(S));

    int i;
    for (i = 1; i < argc; ++i) {
        const char *arg = argv[i];
        if (arg[0] != '-' || arg[1] == '\0') {
            /* positional treated as script file */
            if (S.mode == B_NONE) { S.mode = B_RUN_FILE; S.file = arg; }
            ++i;
            break;
        }
        if (strcmp(arg, "--") == 0) { ++i; break; }

        if (arg[1] == '-') {
            const char *name = arg + 2;
            if (strcmp(name, "help") == 0) { print_help(stdout); return 0; }
            if (strcmp(name, "version") == 0) { print_version(); return 0; }
            if (strcmp(name, "ini") == 0) { print_ini(); return 0; }
            if (strcmp(name, "ini=diff") == 0) { print_ini_diff(); return 0; }
            if (starts_with(name, "ini=")) { print_ini(); return 0; }
            if (strcmp(name, "rf") == 0 || strcmp(name, "rc") == 0 ||
                strcmp(name, "re") == 0 || strcmp(name, "rz") == 0 ||
                strcmp(name, "ri") == 0) {
                if (i + 1 >= argc) { fprintf(stderr, "No name supplied\n"); return 1; }
                if (set_mode(&S, B_REFLECT)) return 1;
                S.refl = name[1];
                S.refl_name = argv[++i];
                continue;
            }
            if (strcmp(name, "repeat") == 0) {
                if (i + 1 >= argc) { fprintf(stderr, "No repeat count supplied\n"); return 1; }
                ++i;
                continue;
            }
            return report_bad_arg(i, 1, "no argument for option", 0);
        }

        /* short option cluster */
        int pos = 1;
        while (arg[pos]) {
            char c = arg[pos];
            if (c == '?' || c == 'h') { print_help(stdout); return 0; }
            if (c == 'v') { print_version(); return 0; }
            if (c == 'm') { print_modules(); return 0; }
            if (c == 'i') { print_info(); return 0; }

            if (!short_known(c)) {
                return report_bad_arg(i, pos + 1, "option not found", c);
            }
            /* known but non-terminal: record behavior */
            if (c == 'a') {
                if (set_mode(&S, B_INTERACTIVE)) return 1;
                ++pos; continue;
            }
            if (c == 'n' || c == 'e' || c == 'H' || c == 's' || c == 'w') {
                ++pos; continue;
            }
            if (c == 'l') {
                if (set_mode(&S, B_LINT)) return 1;
                ++pos; continue;
            }
            if (short_takes_arg(c)) {
                ++pos;
                const char *val;
                if (arg[pos] != '\0') {
                    val = arg + pos;
                    pos = (int)strlen(arg);
                } else if (i + 1 < argc) {
                    val = argv[++i];
                } else {
                    return report_bad_arg(i, pos, "no argument for option", c);
                }
                if (c == 'r') {
                    if (S.code) { fputs("You can use -r only once.\n", stderr); return 1; }
                    if (set_mode(&S, B_RUN_CODE)) return 1;
                    S.code = val;
                } else if (c == 'f') {
                    if (set_mode(&S, B_RUN_FILE)) return 1;
                    S.file = val;
                }
                /* other arg-taking options (c, d, t, B, R, F, E, S): ignored */
                break;
            }
            ++pos;
        }
    }

    /* The positional loop above may leave args after the file; ignored. */
    (void)i;

    switch (S.mode) {
        case B_INTERACTIVE:
            fputs("Interactive shell (-a) requires the readline extension.\n", stderr);
            return 1;
        case B_RUN_CODE:
            return run_code(S.code);
        case B_RUN_FILE:
            return run_file_template(S.file);
        case B_LINT:
            /* With -l but no file, PHP reads stdin; we just succeed silently. */
            if (S.file) return lint_file(S.file);
            return 0;
        case B_REFLECT:
            /* Out-of-scope; best-effort empty output. */
            return 0;
        case B_NONE:
        default:
            break;
    }

    /* No action: if stdin is a pipe/file, stream it (template mode). */
    if (!isatty(fileno(stdin))) {
        size_t cap = 4096, len = 0;
        char *all = (char *)malloc(cap);
        char buf[4096];
        size_t n;
        while ((n = fread(buf, 1, sizeof buf, stdin)) > 0) {
            if (len + n + 1 > cap) {
                while (len + n + 1 > cap) cap *= 2;
                all = (char *)realloc(all, cap);
            }
            memcpy(all + len, buf, n);
            len += n;
        }
        all[len] = '\0';
        const char *p = all;
        while (*p) {
            const char *tag = strstr(p, "<?");
            if (!tag) { fwrite(p, 1, strlen(p), stdout); break; }
            fwrite(p, 1, (size_t)(tag - p), stdout);
            const char *code_start;
            if (starts_with(tag, "<?php")) code_start = tag + 5;
            else if (starts_with(tag, "<?=")) code_start = tag + 3;
            else code_start = tag + 2;
            const char *end = strstr(code_start, "?>");
            size_t clen = end ? (size_t)(end - code_start) : strlen(code_start);
            char *snip = (char *)malloc(clen + 1);
            memcpy(snip, code_start, clen);
            snip[clen] = '\0';
            run_code(snip);
            free(snip);
            if (!end) break;
            p = end + 2;
            if (*p == '\n') ++p;
        }
        free(all);
    }
    return 0;
}
